def _isna_old(obj):
    """
    Detect missing values, treating None, NaN, INF, -INF as null.

    Parameters
    ----------
    obj: scalar, ndarray, or object value

    Returns
    -------
    boolean ndarray or boolean
    """
    if is_scalar(obj):
        return libmissing.checknull_old(obj)  # Handle scalar null checking
    elif isinstance(obj, ABCMultiIndex):
        raise NotImplementedError("isna is not defined for MultiIndex")
    elif isinstance(obj, type):
        return False
    elif isinstance(obj, (ABCSeries, np.ndarray, ABCIndexClass, ABCExtensionArray)):
        return _isna_ndarraylike_old(obj)  # Handle array-like null checking
    elif isinstance(obj, ABCGeneric):
        # Special handling for ABCGeneric types including DateTimeArray
        # Check if it has the method _data and ensure functional compatibility
        if hasattr(obj, "_data") and hasattr(obj._data, "isna"):
            return obj._constructor(obj._data.isna(func=_isna_old))
        else:
            return False  # Return False if not compatible
    elif isinstance(obj, list):
        return _isna_ndarraylike_old(np.asarray(obj, dtype=object))  # Convert list to array
    elif hasattr(obj, "__array__"):  # Check for array-like objects
        return _isna_ndarraylike_old(np.asarray(obj))  # Convert to array and check
    else:
        return obj is None  # Default case for unsupported types
